const ERUN_TYPE_U = 0
const ERUN_TYPE_L = 1
const ERUN_TYPE_UF = 2
const ERUN_TYPE_LF = 3
const ERUN_TYPE_UL = 4
const ERUN_TYPE_LSU = 5
const ERUN_TYPE_U2L_399_EXT2 = 6
